        `ODPANS`,
        `DATOPT`,
        `PAYOPT`,
        `LastDate`,
        `PostingDate`,
        `NextBusinessDate`,
        `YEARMONTH`,
        `LOADED_AT`
    FROM landing_jh.default.jh_ddpar1
),

bronze_data AS (
    SELECT
        `RECID`,
